// utils/audience.js
const COOKIE_NAME = 'audience';
export const AUDIENCES = { RESIDENT: 'RESIDENT', TOURIST: 'TOURIST' };

export function getCookie(name) {
  const match = document.cookie.match(new RegExp('(?:^|; )' + name.replace(/([.$?*|{}()\[\]\\/+^])/g,'\\$1') + '=([^;]*)'));
  return match ? decodeURIComponent(match[1]) : null;
}

export function setCookie(name, value, days = 365) {
  const d = new Date();
  d.setTime(d.getTime() + (days*24*60*60*1000));
  document.cookie = `${name}=${encodeURIComponent(value)}; expires=${d.toUTCString()}; path=/; SameSite=Lax`;
}

export function getAudience() {
  const v = getCookie(COOKIE_NAME);
  if (v === AUDIENCES.RESIDENT || v === AUDIENCES.TOURIST) return v;
  return null;
}

export function setAudience(v) {
  if (!v) return;
  setCookie(COOKIE_NAME, v, 365);
}
